  fields: (t) => ({
    answerCollections: t.field({
      type: [AnswerCollectionRef],
      args: {
        first: t.arg.int(),
        after: t.arg.string({ nullable: true }),
      },
      resolve: async (parent, args) => {
        // Implement cursor-based pagination
      },
    }),
    // Similar implementation for other collections
  }),
})
```

